function v53Esc(v){return String(v??'').replace(/[&<>\"]/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[s]))}
function v53Fmt(v,d=3,u=''){return Number.isFinite(v)?v.toFixed(d)+u:'n/a'}
function v53Card(title,rows,badge=''){return `<section class="v53Card"><header><b>${v53Esc(title)}</b>${badge?`<em>${v53Esc(badge)}</em>`:''}</header>${rows.map(r=>`<div class="v53kv"><span>${v53Esc(r[0])}</span><strong>${v53Esc(r[1])}</strong></div>`).join('')}</section>`}
