const v54Camera={mode:'AUTO',dragLatches:true,panOffset:[0,0,0],panning:false,last:[0,0],followSmoothing:.18,orbitSensitivity:.006,panSensitivity:.0017};
function v54FollowBaseTarget(){return v5add(free.p,v5qrot(free.q,[0,.12,.05]))}
function v54CameraSnapshot(){return{schema:'ducati916.camera-state.v1',mode:v54Camera.mode,currentView,manualPersistent:v54Camera.mode!=='AUTO',yawRad:cam.yaw,pitchRad:cam.pitch,distanceM:cam.dist,targetM:cam.target.slice(),panOffsetM:v54Camera.panOffset.slice(),dragLatches:v54Camera.dragLatches}}
function v54SetCameraMode(mode,preserve=true){
 mode=String(mode||'AUTO').toUpperCase();if(!['AUTO','FOLLOW_ORBIT','WORLD_FREE'].includes(mode))mode='AUTO';
 if(mode==='FOLLOW_ORBIT'){
  let b=v54FollowBaseTarget();if(preserve)v54Camera.panOffset=v5sub(cam.target,b);else v54Camera.panOffset=[0,0,0];
  currentView='freeFollow';v5ChaseInit=false;
 }else if(mode==='WORLD_FREE'){
  currentView='worldFree';v5ChaseInit=false;
 }else{currentView='chase';v54Camera.panOffset=[0,0,0];v5ChaseInit=false}
 v54Camera.mode=mode;v54UpdateCameraUI();return v54CameraSnapshot()
}
function v54RecenterCamera(){v54Camera.mode='AUTO';v54Camera.panOffset=[0,0,0];currentView='chase';v5ChaseInit=false;view('chase');v54UpdateCameraUI();return v54CameraSnapshot()}
function v54CamAxes(){let cp=Math.cos(cam.pitch),eye=[cam.target[0]+cam.dist*cp*Math.sin(cam.yaw),cam.target[1]+cam.dist*cp*Math.cos(cam.yaw),cam.target[2]+cam.dist*Math.sin(cam.pitch)],f=v5norm(v5sub(cam.target,eye)),r=v5norm(v5cross(f,V5_UP));if(v5len(r)<.1)r=[1,0,0];let u=v5norm(v5cross(r,f));return{eye,forward:f,right:r,up:u}}

const v54AutoCameraBase=updateFreeCamera;
updateFreeCamera=function(){
 if(v54Camera.mode==='FOLLOW_ORBIT'||currentView==='freeFollow'){
  let want=v5add(v54FollowBaseTarget(),v54Camera.panOffset),s=v54Camera.followSmoothing;for(let i=0;i<3;i++)cam.target[i]+=(want[i]-cam.target[i])*s;currentView='freeFollow';
 }else if(v54Camera.mode==='WORLD_FREE'||currentView==='worldFree'){
  currentView='worldFree';
 }else v54AutoCameraBase();
 window.__V54_CAMERA_STATE__=v54CameraSnapshot();
};

function v54InstallCameraInput(){
 if(!cvs||cvs.__v54CameraInput)return;cvs.__v54CameraInput=true;
 cvs.oncontextmenu=e=>e.preventDefault();
 cvs.onpointerdown=e=>{
  if(simDomain==='FREE_ROAD'&&v54Camera.dragLatches&&v54Camera.mode==='AUTO')v54SetCameraMode('FOLLOW_ORBIT',true);
  drag=true;v54Camera.panning=!!(e.shiftKey||e.button===2);v54Camera.last=[e.clientX,e.clientY];last=[e.clientX,e.clientY];try{cvs.setPointerCapture(e.pointerId)}catch(_){ }e.preventDefault();
 };
 cvs.onpointerup=e=>{drag=false;v54Camera.panning=false;try{cvs.releasePointerCapture(e.pointerId)}catch(_){ }};
 cvs.onpointercancel=()=>{drag=false;v54Camera.panning=false};
 cvs.onpointermove=e=>{if(!drag)return;let dx=e.clientX-v54Camera.last[0],dy=e.clientY-v54Camera.last[1];v54Camera.last=[e.clientX,e.clientY];last=v54Camera.last.slice();if(v54Camera.panning||e.shiftKey){let A=v54CamAxes(),sc=Math.max(.0002,cam.dist*v54Camera.panSensitivity),d=v5add(v5mul(A.right,-dx*sc),v5mul(A.up,dy*sc));cam.target=v5add(cam.target,d);if(v54Camera.mode==='FOLLOW_ORBIT')v54Camera.panOffset=v5add(v54Camera.panOffset,d)}else{cam.yaw-=dx*v54Camera.orbitSensitivity;cam.pitch=clamp(cam.pitch+dy*v54Camera.orbitSensitivity,-1.52,1.52)}e.preventDefault()};
 cvs.onwheel=e=>{if(simDomain==='FREE_ROAD'&&v54Camera.dragLatches&&v54Camera.mode==='AUTO')v54SetCameraMode('FOLLOW_ORBIT',true);cam.dist=clamp(cam.dist*Math.exp(e.deltaY*.001),.20,50);e.preventDefault()};
 cvs.ondblclick=e=>{if(simDomain==='FREE_ROAD'){v54RecenterCamera();e.preventDefault()}};
}

// ---------------- assistance UI ----------------
function v54Row(label,id,min,max,step,value,unit){return`<div class="row"><span>${label}</span><span class="v" id="${id}V">${value}${unit||''}</span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`}
function v54AssistPanelHTML(){return`
 <div class="sec"><h3>ROLL ANGLE SPRING-DAMPER</h3>
  <label><input id="v54RollEnable" type="checkbox"> enable external roll stabilizer torque</label>
  ${v54Row('Target roll','v54RollTarget',-60,60,.5,0,'°')}
  ${v54Row('Strength','v54RollStrength',0,2.5,.05,1,'×')}
  ${v54Row('Elastic stiffness K','v54RollK',0,3000,25,1100,' N·m/rad')}
  ${v54Row('Damping C','v54RollC',0,500,5,150,' N·m·s/rad')}
  ${v54Row('Torque limit','v54RollMax',0,600,5,260,' N·m')}
  <div id="v54RollAssistState" class="status">OFF · external torque 0 N·m</div>
  <div class="tiny">This is an explicit virtual stabilizer / test-rig torque about the body forward axis. It does not change the quaternion or roll angle directly. Keep OFF for raw motorcycle physics.</div>
 </div>
 <div class="sec"><h3>STEERING ANGLE SPRING-DAMPER</h3>
  <label><input id="v54SteerEnable" type="checkbox"> enable steering angle servo torque</label>
  ${v54Row('Target steering','v54SteerTarget',-30,30,.25,0,'°')}
  ${v54Row('Strength','v54SteerStrength',0,2.5,.05,1,'×')}
  ${v54Row('Elastic stiffness K','v54SteerK',0,150,1,34,' N·m/rad')}
  ${v54Row('Damping C','v54SteerC',0,20,.2,3.2,' N·m·s/rad')}
  ${v54Row('Torque limit','v54SteerMax',0,30,.5,14,' N·m')}
  <div id="v54SteerAssistState" class="status">OFF · servo torque 0 N·m</div>
  <div class="tiny">Adds torque around the physical steering generalized coordinate and remains additive with rider/user steering torque, tire moment, gyro reaction and passive damping/friction.</div>
 </div>
 <div class="sec"><h3>ASSIST CONTROL</h3><div class="buttons"><button id="v54AssistDisable">Disable all</button><button id="v54AssistZeroTargets">Zero targets</button><button id="v54AssistCaptureTargets">Capture current angles</button><button id="v54AssistAudit">Audit assist semantics</button></div><div id="v54AssistAuditState" class="status">Assist audit not run.</div></div>`}
function v54CameraPanelHTML(){return`
 <div class="sec"><h3>PERSISTENT CAMERA</h3><div class="buttons"><button id="v54CamAuto">Auto chase</button><button id="v54CamFollow">Free follow orbit</button><button id="v54CamWorld">World free</button><button id="v54CamRecenter">Re-center</button></div>
 <div class="checks"><label><input id="v54CamLatch" type="checkbox" checked> dragging latches free camera</label></div>
 ${v54Row('Follow target smoothing','v54CamSmooth',0,1,.01,.18,'')}
 ${v54Row('Orbit sensitivity','v54CamOrbit',.001,.015,.0005,.006,'')}
 <div id="v54CameraState" class="status"></div>
 <div class="tiny">Drag = orbit. Shift-drag or right-drag = pan. Wheel = zoom. Double-click = restore automatic chase. In Free Follow, the camera target follows the motorcycle but your angle/zoom/pan remain persistent. World Free does not follow the bike.</div></div>`}

function v54BuildUI(){
 let ctrl=$('ctrl'),tabs=$('v53Tabs');if(!ctrl||!tabs||$('v53PanelASSIST'))return;
 let badge=document.querySelector('#badge .ttl');if(badge)badge.textContent='DUCATI 916 VEHICLE DYNAMICS LAB V5.4 · ASSIST / PERSISTENT CAMERA / TELEMETRY';
 let dFree=$('domainFree');if(dFree)dFree.textContent='V5.4 FREE ROAD';
 let freeSec=[...document.querySelectorAll('#v53PanelRUN .sec')].find(x=>x.querySelector('h3')?.textContent.includes('FREE ROAD'));if(freeSec)freeSec.querySelector('h3').textContent='V5.4 FREE ROAD · COUPLED / ASSIST-INSTRUMENTED';
 let style=document.createElement('style');style.textContent=`.v54AssistOn{border-color:#62dca2!important;box-shadow:0 0 0 1px #62dca233 inset}.v54Sat{color:#ffb567!important}.v54ModeActive{background:#174151!important;border-color:#6fdcff!important}.v54GapList{display:grid;gap:5px}.v54Gap{padding:6px;border:1px solid #354957;border-radius:5px;background:#09151c}.v54Gap b{color:#ffc66c}.v53Tabs{grid-template-columns:repeat(7,1fr)}@media(max-width:1100px){.v53Tabs{grid-template-columns:repeat(4,1fr)}}`;document.head.appendChild(style);
 for(let k of ['ASSIST','CAMERA']){let b=document.createElement('button');b.dataset.v53tab=k;b.textContent=k;tabs.appendChild(b);let p=document.createElement('div');p.id='v53Panel'+k;p.className='v53Panel';p.innerHTML=k==='ASSIST'?v54AssistPanelHTML():v54CameraPanelHTML();ctrl.appendChild(p)}
 tabs.onclick=e=>{let b=e.target.closest('[data-v53tab]');if(!b)return;let k=b.dataset.v53tab;tabs.querySelectorAll('button[data-v53tab]').forEach(x=>x.classList.toggle('active',x===b));ctrl.querySelectorAll(':scope > .v53Panel').forEach(p=>p.classList.toggle('active',p.id==='v53Panel'+k))};
 let audit=$('v53PanelAUDIT');if(audit){let gaps=document.createElement('div');gaps.className='sec';gaps.innerHTML=`<h3>OPEN PHYSICS / OWNERSHIP BLOCKERS</h3><div class="v54GapList"><div class="v54Gap"><b>Steering geometry</b> — source fork/steer offset remains suspect; calibrated geometry not yet promoted.</div><div class="v54Gap"><b>Tire transient dynamics</b> — native aligning moment and relaxation-length states are still absent.</div><div class="v54Gap"><b>Mass ownership</b> — distributed tire particle mass vs 25/22 kg unsprung groups remains under audit.</div><div class="v54Gap"><b>Inertia</b> — roll/yaw sprung-body inertias remain provisional.</div><div class="v54Gap"><b>Powertrain</b> — engine, clutch, gearbox, shift torque interruption and engine braking remain absent.</div><div class="v54Gap"><b>Aerodynamics</b> — drag/lift/aero moments remain absent.</div><div class="v54Gap"><b>Crash geometry</b> — chassis contacts remain coarse proxy shapes rather than full collision geometry.</div></div>`;audit.appendChild(gaps)}
 let vb=$('viewBtns');for(let [id,label,mode] of [['freeFollow','Free Follow','FOLLOW_ORBIT'],['worldFree','World Cam','WORLD_FREE']])if(!vb.querySelector(`[data-view="${id}"]`)){let b=document.createElement('button');b.dataset.view=id;b.textContent=label;vb.appendChild(b);b.onclick=()=>v54SetCameraMode(mode,true)}
}

function v54ReadAssistUI(){return{rollEnabled:!!$('v54RollEnable')?.checked,rollTargetDeg:+($('v54RollTarget')?.value||0),rollStrength:+($('v54RollStrength')?.value||0),rollK:+($('v54RollK')?.value||0),rollC:+($('v54RollC')?.value||0),rollMaxNm:+($('v54RollMax')?.value||0),steerEnabled:!!$('v54SteerEnable')?.checked,steerTargetDeg:+($('v54SteerTarget')?.value||0),steerStrength:+($('v54SteerStrength')?.value||0),steerK:+($('v54SteerK')?.value||0),steerC:+($('v54SteerC')?.value||0),steerMaxNm:+($('v54SteerMax')?.value||0)}}
function v54Label(id,v,unit,d=2){let e=$(id+'V');if(e)e.textContent=Number.isFinite(+v)?(+v).toFixed(d)+(unit||''):'n/a'}
function v54UpdateAssistLabels(){v54Label('v54RollTarget',$('v54RollTarget')?.value,'°',1);v54Label('v54RollStrength',$('v54RollStrength')?.value,'×',2);v54Label('v54RollK',$('v54RollK')?.value,' N·m/rad',0);v54Label('v54RollC',$('v54RollC')?.value,' N·m·s/rad',0);v54Label('v54RollMax',$('v54RollMax')?.value,' N·m',0);v54Label('v54SteerTarget',$('v54SteerTarget')?.value,'°',2);v54Label('v54SteerStrength',$('v54SteerStrength')?.value,'×',2);v54Label('v54SteerK',$('v54SteerK')?.value,' N·m/rad',0);v54Label('v54SteerC',$('v54SteerC')?.value,' N·m·s/rad',1);v54Label('v54SteerMax',$('v54SteerMax')?.value,' N·m',1)}
function v54SyncAssist(){v54UpdateAssistLabels();free.setAssist(v54ReadAssistUI());v54UpdateAssistState()}
function v54UpdateAssistState(){let A=free.last?.assistance;if(!A)return;let r=A.roll,s=A.steering,re=$('v54RollAssistState'),se=$('v54SteerAssistState');let reflect=(id,val)=>{let e=$(id);if(e&&document.activeElement!==e)e.value=String(val)};if($('v54RollEnable'))$('v54RollEnable').checked=!!r.enabled;if($('v54SteerEnable'))$('v54SteerEnable').checked=!!s.enabled;reflect('v54RollTarget',r.targetDeg);reflect('v54RollStrength',r.strength);reflect('v54RollK',r.kNmPerRad);reflect('v54RollC',r.cNmsPerRad);reflect('v54RollMax',r.maxTorqueNm);reflect('v54SteerTarget',s.targetDeg);reflect('v54SteerStrength',s.strength);reflect('v54SteerK',s.kNmPerRad);reflect('v54SteerC',s.cNmsPerRad);reflect('v54SteerMax',s.maxTorqueNm);v54UpdateAssistLabels();if(re){re.classList.toggle('v54AssistOn',r.enabled);re.textContent=`${r.enabled?'ON':'OFF'} · target ${r.targetDeg.toFixed(1)}° · error ${r.errorDeg.toFixed(3)}° · spring ${r.springTorqueNm.toFixed(2)} · damping ${r.dampingTorqueNm.toFixed(2)} · NET ${r.netTorqueNm.toFixed(2)} N·m${r.saturated?' · SATURATED':''}`}if(se){se.classList.toggle('v54AssistOn',s.enabled);se.textContent=`${s.enabled?'ON':'OFF'} · target ${s.targetDeg.toFixed(2)}° · error ${s.errorDeg.toFixed(3)}° · spring ${s.springTorqueNm.toFixed(3)} · damping ${s.dampingTorqueNm.toFixed(3)} · NET ${s.netTorqueNm.toFixed(3)} N·m${s.saturated?' · SATURATED':''}`}}
function v54UpdateCameraUI(){let C=v54CameraSnapshot(),el=$('v54CameraState');if(el)el.textContent=`${C.mode} · yaw ${(C.yawRad/DEG).toFixed(1)}° · pitch ${(C.pitchRad/DEG).toFixed(1)}° · distance ${C.distanceM.toFixed(2)} m\ntarget ${C.targetM.map(x=>x.toFixed(3)).join(' / ')} m`;for(let [id,m] of [['v54CamAuto','AUTO'],['v54CamFollow','FOLLOW_ORBIT'],['v54CamWorld','WORLD_FREE']])$(id)?.classList.toggle('v54ModeActive',v54Camera.mode===m)}

function v54WireUI(){
 let assistIds=['v54RollEnable','v54RollTarget','v54RollStrength','v54RollK','v54RollC','v54RollMax','v54SteerEnable','v54SteerTarget','v54SteerStrength','v54SteerK','v54SteerC','v54SteerMax'];for(let id of assistIds)if($(id)){$(id).oninput=v54SyncAssist;$(id).onchange=v54SyncAssist}
 $('v54AssistDisable').onclick=()=>{$('v54RollEnable').checked=false;$('v54SteerEnable').checked=false;v54SyncAssist()};$('v54AssistZeroTargets').onclick=()=>{$('v54RollTarget').value=0;$('v54SteerTarget').value=0;v54SyncAssist()};$('v54AssistCaptureTargets').onclick=()=>{$('v54RollTarget').value=free.last.body.rollDeg;$('v54SteerTarget').value=free.last.steering.angleDeg;v54SyncAssist()};$('v54AssistAudit').onclick=()=>{let a=free.runAssistAudit();$('v54AssistAuditState').textContent=`assist audit ${a.passed}/${a.total}\n`+a.checks.map(x=>`${x.pass?'PASS':'FAIL'} ${x.name}`).join('\n');window.__V54_ASSIST_AUDIT__=a};
 $('v54CamAuto').onclick=()=>v54RecenterCamera();$('v54CamFollow').onclick=()=>v54SetCameraMode('FOLLOW_ORBIT',true);$('v54CamWorld').onclick=()=>v54SetCameraMode('WORLD_FREE',true);$('v54CamRecenter').onclick=()=>v54RecenterCamera();$('v54CamLatch').onchange=()=>{v54Camera.dragLatches=$('v54CamLatch').checked};$('v54CamSmooth').oninput=()=>{v54Camera.followSmoothing=+$('v54CamSmooth').value;v54Label('v54CamSmooth',v54Camera.followSmoothing,'',2)};$('v54CamOrbit').oninput=()=>{v54Camera.orbitSensitivity=+$('v54CamOrbit').value;v54Label('v54CamOrbit',v54Camera.orbitSensitivity,'',4)};
 v54SyncAssist();v54UpdateCameraUI();v54InstallCameraInput();
}

const v54BaseWire=wireV5UI;wireV5UI=function(){v54BaseWire();v54BuildUI();v54WireUI()};

// ---------------- richer subsystem + every-part telemetry ----------------
function v54AssistCard(M){let A=M.assistance||{},r=A.roll||{},s=A.steering||{},E=A.energy||{};return v53Card('ACTIVE ASSIST / VIRTUAL PRESSURE',[[`roll enabled / target`,`${r.enabled?'ON':'OFF'} / ${v53Fmt(r.targetDeg,2,'°')}`],[`roll error / rate`,`${v53Fmt(r.errorDeg,3,'°')} / ${v53Fmt(r.rateRadS,4,' rad/s')}`],[`roll spring / damping`,`${v53Fmt(r.springTorqueNm,2)} / ${v53Fmt(r.dampingTorqueNm,2)} N·m`],[`roll NET / limit`,`${v53Fmt(r.netTorqueNm,2)} / ${v53Fmt(r.maxTorqueNm,1)} N·m${r.saturated?' SAT':''}`],[`steer enabled / target`,`${s.enabled?'ON':'OFF'} / ${v53Fmt(s.targetDeg,2,'°')}`],[`steer error / rate`,`${v53Fmt(s.errorDeg,3,'°')} / ${v53Fmt(s.rateRadS,4,' rad/s')}`],[`steer spring / damping`,`${v53Fmt(s.springTorqueNm,3)} / ${v53Fmt(s.dampingTorqueNm,3)} N·m`],[`steer NET / limit`,`${v53Fmt(s.netTorqueNm,3)} / ${v53Fmt(s.maxTorqueNm,2)} N·m${s.saturated?' SAT':''}`],[`signed assist work R/S`,`${v53Fmt(E.rollAssistWorkJ,2)} / ${v53Fmt(E.steerAssistWorkJ,2)} J`]],r.enabled||s.enabled?'ASSIST ACTIVE':'OFF')}
function v54DynamicsCard(M){let D=M.dynamics||{},Q=D.generalizedForce||[],A=D.generalizedAccel||[];return v53Card('GENERALIZED DYNAMICS',[[`base accel world`,(D.bodyAccelWorld||[]).map(x=>v53Fmt(x,3)).join(' / ')+' m/s²'],[`angular accel body`,(D.bodyAngularAccelRadS2||[]).map(x=>v53Fmt(x,3)).join(' / ')+' rad/s²'],[`roll Q[4] / α[4]`,`${v53Fmt(Q[4],2,' N·m')} / ${v53Fmt(A[4],3,' rad/s²')}`],[`steer Q[6] / α[6]`,`${v53Fmt(Q[6],3,' N·m')} / ${v53Fmt(A[6],3,' rad/s²')}`],[`fork Q[7] / a[7]`,`${v53Fmt(Q[7],1,' N')} / ${v53Fmt(A[7],3,' m/s²')}`],[`rear swing Q[8] / α[8]`,`${v53Fmt(Q[8],2)} / ${v53Fmt(A[8],3)} generalized`]])}
function v54WheelCard(M){let R=M.wheels.rotor||{};return v53Card('WHEEL ROTOR / ACTUATION',[[`RPM front / rear`,`${v53Fmt(M.wheels.rpmF,1)} / ${v53Fmt(M.wheels.rpmR,1)}`],[`angular momentum F/R`,`${v53Fmt(R.frontAngularMomentumNms,2)} / ${v53Fmt(R.rearAngularMomentumNms,2)} N·m·s`],[`ωdot front / rear`,`${v53Fmt(R.omegaDotF,2)} / ${v53Fmt(R.omegaDotR,2)} rad/s²`],[`tire torque F/R`,`${v53Fmt(M.wheels.tireContactTorqueFrontNm,2)} / ${v53Fmt(M.wheels.tireContactTorqueRearNm,2)} N·m`],[`brake torque F/R`,`${v53Fmt(R.brakeTorqueFrontNm,1)} / ${v53Fmt(R.brakeTorqueRearNm,1)} N·m`],[`rear drive torque`,v53Fmt(R.driveTorqueRearNm,1,' N·m')]])}
const v54BaseTelemetryHTML=v53TelemetryHTML;v53TelemetryHTML=function(M){return[v54AssistCard(M),v54DynamicsCard(M),v54WheelCard(M),v53Card('CAMERA STATE',[[`mode`,v54Camera.mode],[`view`,currentView],[`yaw / pitch`,`${v53Fmt(cam.yaw/DEG,1,'°')} / ${v53Fmt(cam.pitch/DEG,1,'°')}`],[`distance`,v53Fmt(cam.dist,2,' m')],[`target`,cam.target.map(x=>x.toFixed(3)).join(' / ')+' m'],[`drag latches`,v54Camera.dragLatches?'ON':'OFF']],v54Camera.mode==='AUTO'?'AUTO':'PERSISTENT'),v54BaseTelemetryHTML(M)].join('')};

